def gen(rng):
    def fmt(ops):
        return str(len(ops)) + '\n' + '\n'.join(ops)
    def rand_ops(m, users, maxk, ptop, decrease=True):
        names = [rng.choice('abcdefghijklmnopqrstuvwxyz') + str(rng.randint(0, 9999)) for _ in range(users)]
        names = sorted(set(names))
        cur = {}
        ops = ['UPDATE ' + names[0] + ' ' + str(rng.randint(0, maxk))]
        cur[names[0]] = int(ops[0].split()[2])
        while len(ops) < m:
            if rng.random() < ptop:
                ops.append('TOP')
            else:
                nm = rng.choice(names)
                if decrease or nm not in cur:
                    k = rng.randint(0, maxk)
                else:
                    k = min(10**6, cur[nm] + rng.randint(0, maxk))
                cur[nm] = k
                ops.append(f'UPDATE {nm} {k}')
        return ops
    tests = [fmt(['UPDATE a 0', 'TOP']), fmt(['UPDATE a 5', 'UPDATE a 5', 'TOP']),
             fmt(['UPDATE b 1', 'UPDATE a 1', 'TOP', 'UPDATE b 2', 'TOP', 'UPDATE b 0', 'TOP']),
             fmt(['UPDATE u1 10', 'TOP', 'UPDATE u1 0', 'TOP', 'UPDATE u1 7', 'TOP'])]
    for m, users, maxk, pt in ((10, 4, 3, 0.4), (14, 6, 5, 0.3), (20, 12, 4, 0.2), (25, 15, 10, 0.15), (30, 14, 3, 0.2),
                               (30, 12, 100, 0.1), (20, 30, 2, 0.2), (20, 5, 1, 0.5)):
        tests.append(fmt(rand_ops(m, users, maxk, pt)))
    for m, users, maxk, pt in ((12, 12, 6, 0.3), (28, 14, 8, 0.15)):
        tests.append(fmt(rand_ops(m, users, maxk, pt, False)))
    tests.append(fmt(rand_ops(400, 60, 20, 0.3)))
    tests.append(fmt(rand_ops(2000, 300, 10**6, 0.4)))
    # a leaderboard with many ties
    tests.append(fmt(rand_ops(5000, 200, 3, 0.4)))
    # max size: many users first, then lots of TOPs, with changes in between
    M = 60000
    names = ['u' + str(i) for i in range(40000)]
    ops = [f'UPDATE {nm} {rng.randint(0, 2000)}' for nm in names]
    cur = {}
    while len(ops) < M:
        if rng.random() < 0.6:
            ops.append('TOP')
        else:
            ops.append(f'UPDATE {rng.choice(names)} {rng.randint(0, 2000)}')
    tests.append(fmt(ops))
    # all updates first, then TOPs
    ops = [f'UPDATE {nm} {rng.randint(0, 10**6)}' for nm in names] + ['TOP'] * 20000
    tests.append(fmt(ops))
    # alternate update/top, top users keep getting corrected downwards
    ops = [f'UPDATE {nm} {rng.randint(0, 50)}' for nm in names[:20000]]
    best = names[:10]
    while len(ops) < M:
        ops.append(f'UPDATE {rng.choice(best)} {rng.randint(0, 100)}' if rng.random() < 0.5 else 'TOP')
        if len(ops) % 7 == 0:
            ops.append(f'UPDATE {rng.choice(names)} {rng.randint(0, 100)}')
    tests.append(fmt(ops[:M]))
    # only updates
    tests.append(fmt([f'UPDATE {rng.choice(names)} {rng.randint(0, 10**6)}' for _ in range(M - 1)] + ['TOP']))
    return tests

